<script lang="ts">
 import {zh} from './zh';
 import AriaSymbol from './AriaSymbol.svelte';import {chordComplete,chordType,chordErase} from './chord-draft';
 let {kind,phone,landscape,enabled,selectionID,initialText='',measureIndex,onback,oncommit,onfinger,onprevious,onnext}:{kind:'chord'|'lyrics'|'fingering';phone:boolean;landscape:boolean;enabled:boolean;selectionID:string;initialText?:string;measureIndex?:number;onback:()=>void;oncommit:(value:string,advance:boolean,mode?:string,previous?:boolean)=>Promise<boolean>;onfinger:(n:number)=>void;onprevious:()=>void;onnext:()=>void}=$props();
 let draft=$state(''),previousID='',pendingAdvances=0,eraseTimer:ReturnType<typeof setTimeout>;
 $effect(()=>{const id=selectionID,text=initialText;if(id!==previousID){previousID=id;if(pendingAdvances){pendingAdvances--;if(!draft)draft=text;}else draft=text;}});
 const complete=$derived(chordComplete(draft)),changed=$derived(draft!==initialText),removesChord=$derived(!draft&&!!initialText);
 async function commit(advance:boolean,mode?:string,previous=false){const value=draft;if(advance){pendingAdvances++;draft='';}const ok=await oncommit(value,advance,mode,previous);if(!ok&&advance){pendingAdvances=Math.max(0,pendingAdvances-1);if(!draft)draft=value;}return ok;}
 async function chordMove(next:boolean){if(changed&&(complete||removesChord))await commit(true,undefined,!next);else if(next)onnext();else onprevious();}
 function lyricKey(e:KeyboardEvent){if(e.isComposing)return;if([' ','-','_','Enter'].includes(e.key)){e.preventDefault();void commit(e.key!=='Enter',e.key==='-'?'hyphen':e.key==='_'?'melisma':undefined);}else if(e.key==='Escape')onback();}
</script>
<div class="aria-text-panel" class:phone class:landscape class:chord={kind==='chord'} class:lyrics={kind==='lyrics'} class:fingering={kind==='fingering'}>
 {#if kind==='chord'}
  <div class="chord-header"><button aria-label="返回文本工具" class="back" onclick={onback}><AriaSymbol name="chevron.left" size={17}/></button><div class="chord-preview">{draft}<span class="chord-caret"></span></div><button class="done primary" disabled={!!draft&&!complete} onclick={async()=>{if(changed&&(complete||removesChord))await commit(false);onback();}}>完成</button></div>
  <div class="chord-rows">{#each [['C','D','E','F','G','A','B','♭','#'],['maj','min','°','ø','+','sus'],['2','3','4','5','6','7','8','9','11','13'],['add','no','♭5','#5','/','⌫']] as row,index}<div class="chord-key-row" style:grid-template-columns={'repeat('+row.length+',minmax(0,1fr))'}>{#each row as key}<button disabled={!enabled||(!/^[A-G]/.test(draft)&&!['C','D','E','F','G','A','B','⌫'].includes(key))} aria-label={zh(key==='⌫'?'Erase chord character':key)} onpointerdown={()=>{if(key==='⌫')eraseTimer=setTimeout(()=>draft='',600);}} onpointerup={()=>clearTimeout(eraseTimer)} onpointercancel={()=>clearTimeout(eraseTimer)} onclick={()=>draft=key==='⌫'?chordErase(draft):chordType(draft,key.replace('♭','b'))}>{#if key==='⌫'}<AriaSymbol name="delete.left" size={phone?21:25}/>{:else}{key}{/if}</button>{/each}</div>{/each}</div>
  <div class="chord-navigation"><button disabled={!!draft&&!complete} aria-label="前一个和弦位置" onclick={()=>chordMove(false)}><AriaSymbol name="chevron.left" size={16}/>前一项</button><small>{measureIndex==null?'请选择音符':'第 '+(measureIndex+1)+' 小节'}</small><button class="primary" disabled={!!draft&&!complete} aria-label="输入和弦并前进" onclick={()=>chordMove(true)}>输入<AriaSymbol name="chevron.right" size={16}/></button></div>
 {:else if kind==='fingering'}
  <div class="finger-back"><button onclick={onback}><AriaSymbol name="chevron.left" size={16}/>文本</button></div><div class="finger-row">{#each [1,2,3,4,5,0] as finger}<button disabled={!enabled} aria-label={zh(finger?'Fingering '+finger:'Remove fingering')} onclick={()=>onfinger(finger)}>{#if finger}{finger}{:else}<AriaSymbol name="delete.left" size={phone?24:30}/>{/if}</button>{/each}</div>{#if !enabled}<small>选择音符后可添加或移除指法。</small>{/if}
 {:else}
  <div class="lyric-entry"><input aria-label="歌词" placeholder="输入歌词…" bind:value={draft} disabled={!enabled} onkeydown={lyricKey}/><button aria-label="延长歌词音节" disabled={!enabled} onclick={()=>commit(true,'melisma')}><strong>_</strong><small>延长</small></button>{#if !phone}<button aria-label="完成歌词输入" onclick={onback}><AriaSymbol name="checkmark" size={18}/></button>{/if}</div>{#if phone}<p>空格：下一音符 · -：连接音节 · _：延长音节</p>{/if}
 {/if}
</div>
<style>
 .aria-text-panel{color:#000d;font-family:system-ui,sans-serif;}.chord{padding:0 24px 12px;display:grid;gap:8px;}.chord-header{display:flex;gap:12px;align-items:center;}.chord-header button{min-width:76px;}.chord-header .back{width:44px;min-width:44px;margin-right:32px;}.chord-caret{display:inline-block;width:2px;height:28px;background:#007aff;margin-left:3px;vertical-align:middle;animation:caret-blink 1.1s steps(1) infinite;}@keyframes caret-blink{50%{opacity:0;}}.chord-preview{flex:1;text-align:center;font-size:26px;font-weight:600;}.aria-text-panel button{min-height:44px;display:flex;align-items:center;justify-content:center;gap:6px;padding:0 12px;border:0;border-radius:10px;background:#0000000b;color:inherit;font:500 18px system-ui,sans-serif;}.primary{background:#007aff!important;color:white!important;font-weight:600!important;}.chord-rows{display:grid;gap:8px;}.chord-key-row{display:grid;gap:8px;padding-block:2px;}.chord-key-row:first-child button{font-weight:600;}.chord-navigation{display:flex;align-items:center;justify-content:space-between;gap:8px;padding-top:4px;}.chord-navigation>button{font-size:16px;font-weight:600;padding-inline:20px;}.chord-navigation>.primary{padding-inline:32px;}.chord-navigation small{font-size:13px;color:#0008;}.fingering{padding:0 36px 24px;display:flex;align-items:center;flex-direction:column;gap:24px;}.finger-back{align-self:stretch;}.finger-back button{color:#007aff;background:none;font-size:14px;font-weight:600;padding:0;}.finger-row{display:flex;width:100%;max-width:720px;gap:12px;}.finger-row button{flex:1;min-width:0;height:86px;border-radius:16px;background:white;border:1px solid #0000000f;box-shadow:0 3px 5px #00000012;font-size:36px;font-weight:600;}.finger-row button:last-child{background:#0000000d;}.lyrics{padding:12px;background:#ffffffdb;border:1px solid #00000014;border-radius:12px;}.lyric-entry{display:flex;gap:12px;}.lyric-entry input{flex:1;min-width:0;height:48px;border:0;background:transparent;font:18px system-ui,sans-serif;padding:0;outline:none;}.lyric-entry button{flex:none;width:58px;height:48px;display:flex;flex-direction:column;gap:1px;}.lyric-entry strong{font-size:20px;line-height:20px;}.lyric-entry small{font-size:9px;font-weight:600;}.phone.chord{padding:0 8px;gap:4px;}.phone .chord-header{gap:6px;}.phone .chord-header button{min-width:64px;font-size:15px;}.phone .chord-header .back{min-width:44px;margin-right:20px;}.phone .chord-preview{font-size:22px;}.phone .chord-key-row{gap:4px;padding-block:4px;}.phone .chord-key-row:nth-child(3){gap:2px;padding:0;}.phone .chord-key-row:nth-child(3) button{font-size:16px;}.phone .chord-navigation button{font-size:14px;padding-inline:10px;}.phone .chord-navigation .primary{padding-inline:16px;}.phone .chord-navigation small{font-size:11px;}.phone.fingering{padding:0 4px 4px;gap:14px;}.phone .finger-row{gap:8px;}.phone .finger-row button{height:64px;font-size:28px;}.phone.landscape .finger-row button{height:48px;}.phone.lyrics{padding:0;background:none;border:0;border-radius:0;}.phone .lyric-entry{gap:8px;}.phone .lyric-entry input{height:44px;padding:0 12px;border:.7px solid #00000014;background:#0000000a;border-radius:10px;font-size:16px;}.phone .lyric-entry button{width:52px;height:44px;}.phone.lyrics p{margin-top:8px;font-size:12px;font-weight:500;color:#0008;}button:disabled{opacity:.4;}
</style>
